    "\u8bf7\u6839\u636e\u6bcf\u65e5 \u6c14\u6e29 \u5217\u8868 temperatures\u00a0\uff0c\u91cd\u65b0\u751f\u6210\u4e00\u4e2a\u5217\u8868\uff0c\u8981\u6c42\u5176\u5bf9\u5e94\u4f4d\u7f6e\u7684\u8f93\u51fa\u4e3a\uff1a\u8981\u60f3\u89c2\u6d4b\u5230\u66f4\u9ad8\u7684\u6c14\u6e29\uff0c\u81f3\u5c11\u9700\u8981\u7b49\u5f85\u7684\u5929\u6570\u3002\u5982\u679c\u6c14\u6e29\u5728\u8fd9\u4e4b\u540e\u90fd\u4e0d\u4f1a\u5347\u9ad8\uff0c\u8bf7\u5728\u8be5\u4f4d\u7f6e\u7528\u00a00 \u6765\u4ee3\u66ff\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1atemperatures = [73,74,75,71,69,72,76,73]\n\u8f93\u51fa\uff1a[1,1,4,2,1,1,0,0]\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1atemperatures = [30,40,50,60]\n\u8f93\u51fa\uff1a[1,1,1,0]\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1atemperatures = [30,60,90]\n\u8f93\u51fa\uff1a[1,1,0]\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <=\u00a0temperatures.length <= 105\n\n\t30 <=\u00a0temperatures[i]\u00a0<= 100\n\n\u00a0\n\n\u6ce8\u610f\uff1a\u672c\u9898\u4e0e\u4e3b\u7ad9 739\u00a0\u9898\u76f8\u540c\uff1a\u00a0https://leetcode.cn/problems/daily-temperatures/",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1atemperatures\u3002",
    "\u8f93\u51fa integer[] \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def dailyTemperatures(self, temperatures: List[int]) -> List[int]:\n        n = len(temperatures)\n        ans, nxt, big = [0] * n, dict(), 10**9\n        for i in range(n - 1, -1, -1):\n            warmer_index = min(nxt.get(t, big) for t in range(temperatures[i] + 1, 102))\n            if warmer_index != big:\n                ans[i] = warmer_index - i\n            nxt[temperatures[i]] = i\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.dailyTemperatures(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
