    "\u6808/\u961f\u5217",
    "\u53ea\u6709\u6ee1\u8db3\u4e0b\u9762\u51e0\u70b9\u4e4b\u4e00\uff0c\u62ec\u53f7\u5b57\u7b26\u4e32\u624d\u662f\u6709\u6548\u7684\uff1a\n\n\t\u5b83\u662f\u4e00\u4e2a\u7a7a\u5b57\u7b26\u4e32\uff0c\u6216\u8005\n\n\t\u5b83\u53ef\u4ee5\u88ab\u5199\u6210\u00a0AB\u00a0\uff08A\u00a0\u4e0e\u00a0B\u00a0\u8fde\u63a5\uff09, \u5176\u4e2d\u00a0A \u548c\u00a0B\u00a0\u90fd\u662f\u6709\u6548\u5b57\u7b26\u4e32\uff0c\u6216\u8005\n\n\t\u5b83\u53ef\u4ee5\u88ab\u5199\u4f5c\u00a0(A)\uff0c\u5176\u4e2d\u00a0A\u00a0\u662f\u6709\u6548\u5b57\u7b26\u4e32\u3002\n\n\u7ed9\u5b9a\u4e00\u4e2a\u62ec\u53f7\u5b57\u7b26\u4e32 s \uff0c\u5728\u6bcf\u4e00\u6b21\u64cd\u4f5c\u4e2d\uff0c\u4f60\u90fd\u53ef\u4ee5\u5728\u5b57\u7b26\u4e32\u7684\u4efb\u4f55\u4f4d\u7f6e\u63d2\u5165\u4e00\u4e2a\u62ec\u53f7\n\n\t\u4f8b\u5982\uff0c\u5982\u679c s = \"()))\" \uff0c\u4f60\u53ef\u4ee5\u63d2\u5165\u4e00\u4e2a\u5f00\u59cb\u62ec\u53f7\u4e3a \"(()))\" \u6216\u7ed3\u675f\u62ec\u53f7\u4e3a \"())))\" \u3002\n\n\u8fd4\u56de \u4e3a\u4f7f\u7ed3\u679c\u5b57\u7b26\u4e32 s \u6709\u6548\u800c\u5fc5\u987b\u6dfb\u52a0\u7684\u6700\u5c11\u62ec\u53f7\u6570\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1as = \"())\"\n\u8f93\u51fa\uff1a1\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1as = \"(((\"\n\u8f93\u51fa\uff1a3\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= s.length <= 1000\n\n\ts \u53ea\u5305\u542b\u00a0'(' \u548c\u00a0')'\u00a0\u5b57\u7b26\u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1as\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def minAddToMakeValid(self, s: str) -> int:\n        ans = cnt = 0\n        for c in s:\n            if c == '(':\n                cnt += 1\n            elif cnt > 0:\n                cnt -= 1\n            else:\n                ans += 1\n        return ans + cnt\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.minAddToMakeValid(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
