    "\u7ed9\u4f60\u4e0b\u6807\u4ece 0 \u5f00\u59cb\u3001\u957f\u5ea6\u4e3a n\u00a0\u7684\u5b57\u7b26\u4e32\u00a0pattern\u00a0\uff0c\u5b83\u5305\u542b\u4e24\u79cd\u5b57\u7b26\uff0c'I'\u00a0\u8868\u793a \u4e0a\u5347\u00a0\uff0c'D'\u00a0\u8868\u793a \u4e0b\u964d\u00a0\u3002\n\n\u4f60\u9700\u8981\u6784\u9020\u4e00\u4e2a\u4e0b\u6807\u4ece 0\u00a0\u5f00\u59cb\u957f\u5ea6\u4e3a\u00a0n + 1\u00a0\u7684\u5b57\u7b26\u4e32\uff0c\u4e14\u5b83\u8981\u6ee1\u8db3\u4ee5\u4e0b\u6761\u4ef6\uff1a\n\n\tnum\u00a0\u5305\u542b\u6570\u5b57\u00a0'1'\u00a0\u5230\u00a0'9'\u00a0\uff0c\u5176\u4e2d\u6bcf\u4e2a\u6570\u5b57\u00a0\u81f3\u591a\u00a0\u4f7f\u7528\u4e00\u6b21\u3002\n\n\t\u5982\u679c\u00a0pattern[i] == 'I'\u00a0\uff0c\u90a3\u4e48\u00a0num[i] < num[i + 1]\u00a0\u3002\n\n\t\u5982\u679c\u00a0pattern[i] == 'D'\u00a0\uff0c\u90a3\u4e48\u00a0num[i] > num[i + 1]\u00a0\u3002\n\n\u8bf7\u4f60\u8fd4\u56de\u6ee1\u8db3\u4e0a\u8ff0\u6761\u4ef6\u5b57\u5178\u5e8f \u6700\u5c0f\u00a0\u7684\u5b57\u7b26\u4e32\u00a0num\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1apattern = \"IIIDIDDD\"\n\u8f93\u51fa\uff1a\"123549876\"\n\u89e3\u91ca\uff1a\n\u4e0b\u6807 0 \uff0c1 \uff0c2 \u548c 4 \u5904\uff0c\u6211\u4eec\u9700\u8981\u4f7f num[i]  num[i+1] \u3002\n\u4e00\u4e9b\u53ef\u80fd\u7684 num \u7684\u503c\u4e3a \"245639871\" \uff0c\"135749862\" \u548c \"123849765\" \u3002\n\"123549876\" \u662f\u6ee1\u8db3\u6761\u4ef6\u6700\u5c0f\u7684\u6570\u5b57\u3002\n\u6ce8\u610f\uff0c\"123414321\" \u4e0d\u662f\u53ef\u884c\u89e3\u56e0\u4e3a\u6570\u5b57 '1' \u4f7f\u7528\u6b21\u6570\u8d85\u8fc7 1 \u6b21\u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1apattern = \"DDD\"\n\u8f93\u51fa\uff1a\"4321\"\n\u89e3\u91ca\uff1a\n\u4e00\u4e9b\u53ef\u80fd\u7684 num \u7684\u503c\u4e3a \"9876\" \uff0c\"7321\" \u548c \"8742\" \u3002\n\"4321\" \u662f\u6ee1\u8db3\u6761\u4ef6\u6700\u5c0f\u7684\u6570\u5b57\u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= pattern.length <= 8\n\n\tpattern\u00a0\u53ea\u5305\u542b\u5b57\u7b26\u00a0'I' \u548c\u00a0'D' \u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1apattern\u3002",
    "\u8f93\u51fa string \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\r\n    def smallestNumber(self, pattern: str) -> str:\r\n        n = len(pattern)\r\n        ans = [\"\" for _ in range(n + 1)]\r\n        inDegree = [0 for _ in range(n + 1)]\r\n        g = defaultdict(list)\r\n        for idx, val in enumerate(pattern):\r\n            if val == \"I\":\r\n                g[idx].append(idx + 1)\r\n                inDegree[idx + 1] += 1\r\n            elif val == \"D\":\r\n                g[idx + 1].append(idx)\r\n                inDegree[idx] += 1\r\n        queue = []\r\n        for i in range(n + 1):\r\n            if inDegree[i] == 0:\r\n                heapq.heappush(queue, i)\r\n        count = 1\r\n        while queue:\r\n            node = heapq.heappop(queue)\r\n            ans[node] = str(count)\r\n            count += 1\r\n            edges = g[node]\r\n            for edge in edges:\r\n                inDegree[edge] -= 1\r\n                if inDegree[edge] == 0:\r\n                    heapq.heappush(queue, edge)\r\n        return \"\".join(ans)\r\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.smallestNumber(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "str",
    [["\"IIIDIDDD\"", "123549876"], ["\"DDD\"", "4321"]],
    ["stack", "greedy", "string", "backtracking", "\u6808/\u961f\u5217"],
