    "\u7ed9\u5b9a\u4e00\u4e2a\u5e73\u8861\u62ec\u53f7\u5b57\u7b26\u4e32\u00a0S\uff0c\u6309\u4e0b\u8ff0\u89c4\u5219\u8ba1\u7b97\u8be5\u5b57\u7b26\u4e32\u7684\u5206\u6570\uff1a\n\n\t() \u5f97 1 \u5206\u3002\n\n\tAB \u5f97\u00a0A + B\u00a0\u5206\uff0c\u5176\u4e2d A \u548c B \u662f\u5e73\u8861\u62ec\u53f7\u5b57\u7b26\u4e32\u3002\n\n\t(A) \u5f97\u00a02 * A\u00a0\u5206\uff0c\u5176\u4e2d A \u662f\u5e73\u8861\u62ec\u53f7\u5b57\u7b26\u4e32\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1a \"()\"\n\u8f93\u51fa\uff1a 1\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1a \"(())\"\n\u8f93\u51fa\uff1a 2\n```\n\n\u793a\u4f8b\u00a03\uff1a\n\n```\n\u8f93\u5165\uff1a \"()()\"\n\u8f93\u51fa\uff1a 2\n```\n\n\u793a\u4f8b\u00a04\uff1a\n\n```\n\u8f93\u5165\uff1a \"(()(()))\"\n\u8f93\u51fa\uff1a 6\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\tS\u00a0\u662f\u5e73\u8861\u62ec\u53f7\u5b57\u7b26\u4e32\uff0c\u4e14\u53ea\u542b\u6709\u00a0(\u00a0\u548c\u00a0)\u00a0\u3002\n\n\t2 <= S.length <= 50",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1as\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def scoreOfParentheses(self, s: str) -> int:\n        n = len(s)\n        if n == 2:\n            return 1\n        bal = 0\n        for i, c in enumerate(s):\n            bal += 1 if c == '(' else -1\n            if bal == 0:\n                if i == n - 1:\n                    return 2 * self.scoreOfParentheses(s[1:-1])\n                return self.scoreOfParentheses(s[:i + 1]) + self.scoreOfParentheses(s[i + 1:])\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.scoreOfParentheses(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
